-- Exact technical copy upgrade; old publications and acceptances remain immutable.
-- Runs atomically under the ordinary migration runner. Empty installations use seeds.
-- Unknown edits in a published target field abort before any publication is committed.
CREATE FUNCTION pg_temp.transcript_copy_leaf(value jsonb, old_values jsonb, replacement text)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE result jsonb; pair record;
BEGIN
  IF jsonb_typeof(value) = 'string' THEN
    IF old_values ? (value #>> '{}') THEN RETURN to_jsonb(replacement); END IF;
    RETURN value;
  ELSIF jsonb_typeof(value) = 'array' THEN
    SELECT COALESCE(jsonb_agg(pg_temp.transcript_copy_leaf(item,old_values,replacement) ORDER BY n),'[]'::jsonb)
      INTO result FROM jsonb_array_elements(value) WITH ORDINALITY a(item,n);
    RETURN result;
  ELSIF jsonb_typeof(value) = 'object' THEN
    SELECT COALESCE(jsonb_object_agg(key,pg_temp.transcript_copy_leaf(val,old_values,replacement)),'{}'::jsonb)
      INTO result FROM jsonb_each(value) a(key,val);
    RETURN result;
  END IF;
  RETURN value;
END; $$;

CREATE FUNCTION pg_temp.transcript_copy_contains(value jsonb, expected text)
RETURNS boolean LANGUAGE plpgsql AS $$
BEGIN
  IF jsonb_typeof(value)='string' THEN RETURN (value #>> '{}')=expected;
  ELSIF jsonb_typeof(value)='array' THEN
    RETURN EXISTS(SELECT 1 FROM jsonb_array_elements(value) a(item) WHERE pg_temp.transcript_copy_contains(item,expected));
  ELSIF jsonb_typeof(value)='object' THEN
    RETURN EXISTS(SELECT 1 FROM jsonb_each(value) a(key,item) WHERE pg_temp.transcript_copy_contains(item,expected));
  END IF;
  RETURN false;
END; $$;

CREATE FUNCTION pg_temp.transcript_copy_upgrade(value jsonb, group_key text, locale_key text, strict boolean)
RETURNS jsonb LANGUAGE plpgsql AS $function$
DECLARE rule jsonb; found boolean;
BEGIN
  FOR rule IN SELECT item FROM jsonb_array_elements($copy$[{"group":"page:privacy","locale":"en","semantic":"transcript","old":["After consent, SHPROHLI can show a live transcript during the call and create a final transcript from the recording after the call. Live and final transcripts are generated by AI and may contain mistakes. Important names, dates, numbers and commitments should be checked against the recording while it is available."],"next":"After consent, SHPROHLI shows the conversation transcript during the call and saves it afterwards. When this transcript is unavailable or incomplete, the recording may be transcribed instead. The saved transcript is the source for translations, summaries and PDF exports. AI can make mistakes. Check important names, dates, numbers and commitments against the recording while it is available."},{"group":"page:privacy","locale":"en","semantic":"retention","old":["Audio retention is selected for each call: delete the recording after the final transcript is created, keep it for 7 days, or keep it for 30 days. The first option still involves temporary recording; it does not delete the transcript. Translation or summary processing does not extend audio retention. Other account and call data, including saved translations and summaries where enabled, is retained while it is needed to provide the service, meet the selected settings, protect the service and comply with applicable obligations."],"next":"Audio retention is selected for each call: delete the recording after the conversation transcript is saved, keep it for 7 days, or keep it for 30 days. The first option still involves temporary recording; it does not delete the transcript. Translation or summary processing does not extend audio retention. Other account and call data, including saved translations and summaries where enabled, is retained while it is needed to provide the service, meet the selected settings, protect the service and comply with applicable obligations."},{"group":"page:terms","locale":"en","semantic":"service","old":["Before the call, you review the plan and the information the assistant may share. During the conversation, SHPROHLI uses that information as needed. You can follow the transcript and stop the call. SHPROHLI identifies itself as an AI assistant and asks the recipient whether the conversation may be recorded and transcribed. Their answer is processed by AI to recognise the choice. The main conversation and recording start only after consent. SHPROHLI can show a live transcript and create a final transcript after the call. With your explicit approval of the service and date/time limits, SHPROHLI may either book or confirm one appointment with the called recipient. Confirming an existing appointment requires its exact date and time. A new booking uses the first offered time that meets your limits. Rescheduling, cancellations, payments, deposits and new financial or cancellation terms are excluded. The recipient must confirm the appointment during the call; a proposed time alone is not a confirmed booking. SHPROHLI has no access to the recipient's calendar."],"next":"Before the call, you review the plan and the information the assistant may share. During the conversation, SHPROHLI uses that information as needed. You can follow the transcript and stop the call. SHPROHLI identifies itself as an AI assistant and asks the recipient whether the conversation may be recorded and transcribed. Their answer is processed by AI to recognise the choice. The main conversation and recording start only after consent. SHPROHLI shows the conversation transcript and saves it after the call, using transcription of the recording as a fallback. With your explicit approval of the service and date/time limits, SHPROHLI may either book or confirm one appointment with the called recipient. Confirming an existing appointment requires its exact date and time. A new booking uses the first offered time that meets your limits. Rescheduling, cancellations, payments, deposits and new financial or cancellation terms are excluded. The recipient must confirm the appointment during the call; a proposed time alone is not a confirmed booking. SHPROHLI has no access to the recipient's calendar."},{"group":"page:terms","locale":"en","semantic":"limitations","old":["AI conversations, live transcripts and final transcripts can be incomplete, inaccurate or unexpected. Check important names, dates, numbers, instructions and commitments. Do not rely on SHPROHLI for urgent or high-risk decisions."],"next":"AI conversations and transcripts can be incomplete, inaccurate or unexpected. Check important names, dates, numbers, instructions and commitments. Do not rely on SHPROHLI for urgent or high-risk decisions."},{"group":"page:faq","locale":"en","semantic":"accuracy","old":["No. Live and final transcripts are generated by AI and can contain errors. Check important names, dates, numbers and commitments against the recording while it is available."],"next":"No. AI transcripts can contain errors. SHPROHLI normally saves the transcript produced during the conversation; if it is unavailable or incomplete, the recording may be transcribed instead. Translations, summaries and PDF exports use the saved transcript. Check important details against the recording while it is available."},{"group":"collection:faq","locale":"en","semantic":"accuracy","old":["No. Live and final transcripts are generated by AI and can contain errors. Check important names, dates, numbers and commitments against the recording while it is available."],"next":"No. AI transcripts can contain errors. SHPROHLI normally saves the transcript produced during the conversation; if it is unavailable or incomplete, the recording may be transcribed instead. Translations, summaries and PDF exports use the saved transcript. Check important details against the recording while it is available."},{"group":"collection:landing","locale":"en","semantic":"step","old":["Follow the live transcript and review the final transcript afterwards."],"next":"Follow the conversation transcript and read it again after the call."},{"group":"collection:landing","locale":"en","semantic":"retention","old":["You choose whether the recording is deleted after final transcription or kept for 7 or 30 days."],"next":"You choose whether the recording is deleted after the conversation transcript is saved or kept for 7 or 30 days."},{"group":"page:privacy","locale":"de","semantic":"transcript","old":["Nach der Zustimmung kann SHPROHLI während des Anrufs ein Live-Transkript anzeigen und danach aus der Aufnahme ein Endtranskript erstellen. Beide Transkripte werden mit KI erstellt und können Fehler enthalten. Wichtige Namen, Daten, Zahlen und Zusagen sollten Sie mit der Aufnahme vergleichen, solange diese verfügbar ist."],"next":"Nach der Zustimmung zeigt SHPROHLI das Gesprächstranskript während des Anrufs an und speichert es danach. Ist dieses Transkript nicht verfügbar oder unvollständig, kann stattdessen die Aufnahme transkribiert werden. Das gespeicherte Transkript ist die Grundlage für Übersetzungen, Zusammenfassungen und PDF-Exporte. KI kann Fehler machen. Prüfen Sie wichtige Namen, Daten, Zahlen und Zusagen anhand der Aufnahme, solange sie verfügbar ist."},{"group":"page:privacy","locale":"de","semantic":"retention","old":["Für jeden Anruf wählen Sie eine Audioaufbewahrung: Aufnahme nach Erstellung des Endtranskripts löschen, 7 Tage aufbewahren oder 30 Tage aufbewahren. Auch die erste Option umfasst eine vorübergehende Aufnahme; das Transkript wird dabei nicht gelöscht. Übersetzungen und Zusammenfassungen verlängern die Audioaufbewahrung nicht. Andere Konto- und Anrufdaten, einschliesslich gespeicherter Übersetzungen und Zusammenfassungen bei freigeschalteten Funktionen, werden so lange gespeichert, wie dies für den Dienst, Ihre Einstellungen, den Schutz des Dienstes oder anwendbare Pflichten erforderlich ist."],"next":"Für jeden Anruf wählen Sie eine Audioaufbewahrung: Aufnahme nach Speicherung des Gesprächstranskripts löschen, 7 Tage aufbewahren oder 30 Tage aufbewahren. Auch die erste Option umfasst eine vorübergehende Aufnahme; das Transkript wird dabei nicht gelöscht. Übersetzungen und Zusammenfassungen verlängern die Audioaufbewahrung nicht. Andere Konto- und Anrufdaten, einschliesslich gespeicherter Übersetzungen und Zusammenfassungen bei freigeschalteten Funktionen, werden so lange gespeichert, wie dies für den Dienst, Ihre Einstellungen, den Schutz des Dienstes oder anwendbare Pflichten erforderlich ist."},{"group":"page:terms","locale":"de","semantic":"service","old":["Vor dem Anruf prüfen Sie den Plan und die Angaben, die der Assistent weitergeben darf. Während des Gesprächs nutzt SHPROHLI diese Angaben nach Bedarf. Sie können das Transkript verfolgen und den Anruf beenden. SHPROHLI stellt sich als KI-Assistent vor und fragt, ob das Gespräch aufgezeichnet und transkribiert werden darf. Die Antwort wird durch KI verarbeitet, um die Entscheidung zu erkennen. Das eigentliche Gespräch und die Aufzeichnung beginnen erst nach der Zustimmung. SHPROHLI kann ein Live-Transkript anzeigen und nach dem Anruf ein Endtranskript erstellen. Mit Ihrer ausdrücklichen Freigabe der Leistung und der Zeitfenster kann SHPROHLI bei der angerufenen Stelle entweder einen Termin vereinbaren oder einen bestehenden Termin bestätigen. Für die Bestätigung eines bestehenden Termins sind das genaue Datum und die Uhrzeit erforderlich. Bei einer neuen Buchung wird der erste angebotene Termin gewählt, der zu Ihren Vorgaben passt. Verschieben, Absagen, Zahlungen, Anzahlungen sowie neue finanzielle Bedingungen oder Stornogebühren sind ausgeschlossen. Die angerufene Person muss den Termin im Gespräch bestätigen; ein Vorschlag allein ist keine bestätigte Buchung. SHPROHLI hat keinen Zugriff auf deren Kalender."],"next":"Vor dem Anruf prüfen Sie den Plan und die Angaben, die der Assistent weitergeben darf. Während des Gesprächs nutzt SHPROHLI diese Angaben nach Bedarf. Sie können das Transkript verfolgen und den Anruf beenden. SHPROHLI stellt sich als KI-Assistent vor und fragt, ob das Gespräch aufgezeichnet und transkribiert werden darf. Die Antwort wird durch KI verarbeitet, um die Entscheidung zu erkennen. Das eigentliche Gespräch und die Aufzeichnung beginnen erst nach der Zustimmung. SHPROHLI zeigt das Gesprächstranskript an und speichert es nach dem Anruf; die Transkription der Aufnahme dient als Ersatz. Mit Ihrer ausdrücklichen Freigabe der Leistung und der Zeitfenster kann SHPROHLI bei der angerufenen Stelle entweder einen Termin vereinbaren oder einen bestehenden Termin bestätigen. Für die Bestätigung eines bestehenden Termins sind das genaue Datum und die Uhrzeit erforderlich. Bei einer neuen Buchung wird der erste angebotene Termin gewählt, der zu Ihren Vorgaben passt. Verschieben, Absagen, Zahlungen, Anzahlungen sowie neue finanzielle Bedingungen oder Stornogebühren sind ausgeschlossen. Die angerufene Person muss den Termin im Gespräch bestätigen; ein Vorschlag allein ist keine bestätigte Buchung. SHPROHLI hat keinen Zugriff auf deren Kalender."},{"group":"page:terms","locale":"de","semantic":"limitations","old":["KI-Gespräche, Live-Transkripte und Endtranskripte können unvollständig, ungenau oder unerwartet sein. Prüfen Sie wichtige Namen, Daten, Zahlen, Anweisungen und Zusagen. Verlassen Sie sich bei dringenden oder risikoreichen Entscheidungen nicht auf SHPROHLI."],"next":"KI-Gespräche und Transkripte können unvollständig, ungenau oder unerwartet sein. Prüfen Sie wichtige Namen, Daten, Zahlen, Anweisungen und Zusagen. Verlassen Sie sich bei dringenden oder risikoreichen Entscheidungen nicht auf SHPROHLI."},{"group":"page:faq","locale":"de","semantic":"accuracy","old":["Nein. Live- und Endtranskripte werden mit KI erstellt und können Fehler enthalten. Prüfen Sie wichtige Namen, Daten, Zahlen und Zusagen mit der Aufnahme, solange diese verfügbar ist."],"next":"Nein. KI-Transkripte können Fehler enthalten. SHPROHLI speichert normalerweise das während des Gesprächs erstellte Transkript. Ist es nicht verfügbar oder unvollständig, kann stattdessen die Aufnahme transkribiert werden. Übersetzungen, Zusammenfassungen und PDF-Exporte verwenden das gespeicherte Transkript. Prüfen Sie wichtige Angaben anhand der verfügbaren Aufnahme."},{"group":"collection:faq","locale":"de","semantic":"accuracy","old":["Nein. Live- und Endtranskripte werden mit KI erstellt und können Fehler enthalten. Prüfen Sie wichtige Namen, Daten, Zahlen und Zusagen mit der Aufnahme, solange diese verfügbar ist."],"next":"Nein. KI-Transkripte können Fehler enthalten. SHPROHLI speichert normalerweise das während des Gesprächs erstellte Transkript. Ist es nicht verfügbar oder unvollständig, kann stattdessen die Aufnahme transkribiert werden. Übersetzungen, Zusammenfassungen und PDF-Exporte verwenden das gespeicherte Transkript. Prüfen Sie wichtige Angaben anhand der verfügbaren Aufnahme."},{"group":"collection:landing","locale":"de","semantic":"step","old":["Verfolgen Sie das Live-Transkript und prüfen Sie danach das Endtranskript."],"next":"Verfolgen Sie das Gesprächstranskript und lesen Sie es nach dem Anruf erneut."},{"group":"collection:landing","locale":"de","semantic":"retention","old":["Sie wählen, ob die Aufnahme nach dem Endtranskript gelöscht oder 7 beziehungsweise 30 Tage aufbewahrt wird."],"next":"Sie wählen, ob die Aufnahme nach Speicherung des Gesprächstranskripts gelöscht oder 7 beziehungsweise 30 Tage aufbewahrt wird."},{"group":"page:privacy","locale":"fr","semantic":"transcript","old":["Après consentement, SHPROHLI peut afficher une transcription en direct et créer la transcription finale à partir de l’enregistrement. Ces textes sont générés par IA et peuvent contenir des erreurs. Vérifiez les noms, dates, chiffres et engagements importants dans l’enregistrement tant qu’il est disponible."],"next":"Après consentement, SHPROHLI affiche la transcription pendant la conversation et la conserve ensuite. Si elle est indisponible ou incomplète, l’enregistrement peut être transcrit à la place. La transcription conservée sert de source aux traductions, résumés et exports PDF. L’IA peut faire des erreurs. Vérifiez les noms, dates, chiffres et engagements importants dans l’enregistrement tant qu’il est disponible."},{"group":"page:privacy","locale":"fr","semantic":"retention","old":["Pour chaque appel, vous choisissez de supprimer l’audio après la transcription finale ou de le conserver 7 ou 30 jours. La première option implique un enregistrement temporaire et ne supprime pas la transcription. Traductions et résumés ne prolongent pas la conservation audio. Les autres données de compte et d’appel, y compris les traductions et résumés enregistrés, sont conservées tant que nécessaire pour fournir le service, respecter vos réglages, protéger le service et remplir les obligations applicables."],"next":"Pour chaque appel, vous choisissez de supprimer l’audio après la sauvegarde de la transcription de la conversation ou de le conserver 7 ou 30 jours. La première option implique un enregistrement temporaire et ne supprime pas la transcription. Traductions et résumés ne prolongent pas la conservation audio. Les autres données de compte et d’appel, y compris les traductions et résumés enregistrés, sont conservées tant que nécessaire pour fournir le service, respecter vos réglages, protéger le service et remplir les obligations applicables."},{"group":"page:terms","locale":"fr","semantic":"service","old":["Avant l'appel, vous vérifiez le plan et les informations que l'assistant peut partager. Pendant la conversation, SHPROHLI les utilise selon les besoins. Vous pouvez suivre la transcription et arrêter l'appel. SHPROHLI se présente comme un assistant IA et demande à la personne si la conversation peut être enregistrée et transcrite. Sa réponse est analysée par l'IA pour reconnaître son choix. La conversation principale et l'enregistrement ne commencent qu'après son consentement. SHPROHLI peut afficher une transcription en direct et créer une transcription finale après l'appel. Avec votre accord explicite sur la prestation et les limites de date et d'heure, SHPROHLI peut prendre ou confirmer un seul rendez-vous auprès de la personne appelée. Pour confirmer un rendez-vous existant, sa date et son heure exactes sont nécessaires. Pour un nouveau rendez-vous, le premier créneau proposé qui respecte vos limites est retenu. Les déplacements de rendez-vous, annulations, paiements, acomptes et nouvelles conditions financières ou d'annulation sont exclus. La personne appelée doit confirmer le rendez-vous pendant l'appel : une simple proposition ne vaut pas confirmation. SHPROHLI n'a pas accès à son agenda."],"next":"Avant l'appel, vous vérifiez le plan et les informations que l'assistant peut partager. Pendant la conversation, SHPROHLI les utilise selon les besoins. Vous pouvez suivre la transcription et arrêter l'appel. SHPROHLI se présente comme un assistant IA et demande à la personne si la conversation peut être enregistrée et transcrite. Sa réponse est analysée par l'IA pour reconnaître son choix. La conversation principale et l'enregistrement ne commencent qu'après son consentement. SHPROHLI affiche la transcription de la conversation et la conserve après l’appel ; la transcription de l’enregistrement sert de solution de secours. Avec votre accord explicite sur la prestation et les limites de date et d'heure, SHPROHLI peut prendre ou confirmer un seul rendez-vous auprès de la personne appelée. Pour confirmer un rendez-vous existant, sa date et son heure exactes sont nécessaires. Pour un nouveau rendez-vous, le premier créneau proposé qui respecte vos limites est retenu. Les déplacements de rendez-vous, annulations, paiements, acomptes et nouvelles conditions financières ou d'annulation sont exclus. La personne appelée doit confirmer le rendez-vous pendant l'appel : une simple proposition ne vaut pas confirmation. SHPROHLI n'a pas accès à son agenda."},{"group":"page:faq","locale":"fr","semantic":"accuracy","old":["Non. Les transcriptions en direct et finales sont générées par l'IA et peuvent contenir des erreurs. Vérifiez les noms, dates, chiffres et engagements importants à l'aide de l'enregistrement tant qu'il est disponible."],"next":"Non. Les transcriptions IA peuvent contenir des erreurs. SHPROHLI conserve normalement la transcription produite pendant la conversation. Si elle est indisponible ou incomplète, l’enregistrement peut être transcrit à la place. Les traductions, résumés et exports PDF utilisent la transcription conservée. Vérifiez les détails importants dans l’enregistrement disponible."},{"group":"collection:faq","locale":"fr","semantic":"accuracy","old":["Non. Les transcriptions en direct et finales sont générées par l'IA et peuvent contenir des erreurs. Vérifiez les noms, dates, chiffres et engagements importants à l'aide de l'enregistrement tant qu'il est disponible."],"next":"Non. Les transcriptions IA peuvent contenir des erreurs. SHPROHLI conserve normalement la transcription produite pendant la conversation. Si elle est indisponible ou incomplète, l’enregistrement peut être transcrit à la place. Les traductions, résumés et exports PDF utilisent la transcription conservée. Vérifiez les détails importants dans l’enregistrement disponible."},{"group":"collection:landing","locale":"fr","semantic":"step","old":["Suivez la transcription en direct, puis consultez la transcription finale."],"next":"Suivez la transcription de la conversation et relisez-la après l’appel."},{"group":"collection:landing","locale":"fr","semantic":"retention","old":["Vous choisissez de supprimer l'enregistrement après la transcription finale ou de le conserver 7 ou 30 jours."],"next":"Vous choisissez de supprimer l’enregistrement après la sauvegarde de la transcription de la conversation ou de le conserver 7 ou 30 jours."},{"group":"page:privacy","locale":"it","semantic":"transcript","old":["Dopo il consenso, SHPROHLI può mostrare una trascrizione in diretta e creare quella finale dalla registrazione. Sono testi generati dall’IA e possono contenere errori. Verifica nomi, date, numeri e impegni importanti nella registrazione finché è disponibile."],"next":"Dopo il consenso, SHPROHLI mostra la trascrizione durante la conversazione e la salva al termine. Se non è disponibile o è incompleta, può essere trascritta la registrazione. La trascrizione salvata è la fonte per traduzioni, riepiloghi ed esportazioni PDF. L’IA può commettere errori. Verifichi nomi, date, numeri e impegni importanti nella registrazione finché è disponibile."},{"group":"page:privacy","locale":"it","semantic":"retention","old":["Per ogni chiamata scegli se eliminare l’audio dopo la trascrizione finale o conservarlo per 7 o 30 giorni. La prima opzione comporta comunque una registrazione temporanea e non elimina la trascrizione. Traduzioni e riepiloghi non prolungano la conservazione audio. Gli altri dati dell’account e delle chiamate, incluse traduzioni e riepiloghi salvati, sono conservati finché servono per fornire e proteggere il servizio, rispettare le impostazioni e gli obblighi applicabili."],"next":"Per ogni chiamata scegli se eliminare l’audio dopo il salvataggio della trascrizione della conversazione o conservarlo per 7 o 30 giorni. La prima opzione comporta comunque una registrazione temporanea e non elimina la trascrizione. Traduzioni e riepiloghi non prolungano la conservazione audio. Gli altri dati dell’account e delle chiamate, incluse traduzioni e riepiloghi salvati, sono conservati finché servono per fornire e proteggere il servizio, rispettare le impostazioni e gli obblighi applicabili."},{"group":"page:terms","locale":"it","semantic":"service","old":["Prima della chiamata controlli il piano e le informazioni che l'assistente può condividere. Durante la conversazione SHPROHLI le usa quando servono. Puoi seguire la trascrizione e interrompere la chiamata. SHPROHLI si presenta come assistente IA e chiede al destinatario se la conversazione può essere registrata e trascritta. La risposta viene elaborata dall'IA per riconoscere la scelta. La conversazione principale e la registrazione iniziano solo dopo il consenso. SHPROHLI può mostrare una trascrizione in diretta e crearne una finale dopo la chiamata. Con la tua autorizzazione esplicita sul servizio e sui limiti di data e ora, SHPROHLI può prenotare o confermare un solo appuntamento con il destinatario. Per confermarne uno esistente servono la data e l'ora esatte. Per una nuova prenotazione viene scelto il primo orario proposto che rispetta i tuoi limiti. Sono esclusi spostamenti, cancellazioni, pagamenti, acconti e nuove condizioni finanziarie o di cancellazione. Il destinatario deve confermare l'appuntamento durante la chiamata: una proposta da sola non è una conferma. SHPROHLI non ha accesso alla sua agenda."],"next":"Prima della chiamata controlli il piano e le informazioni che l'assistente può condividere. Durante la conversazione SHPROHLI le usa quando servono. Puoi seguire la trascrizione e interrompere la chiamata. SHPROHLI si presenta come assistente IA e chiede al destinatario se la conversazione può essere registrata e trascritta. La risposta viene elaborata dall'IA per riconoscere la scelta. La conversazione principale e la registrazione iniziano solo dopo il consenso. SHPROHLI mostra la trascrizione della conversazione e la salva dopo la chiamata; la trascrizione della registrazione è una soluzione di riserva. Con la tua autorizzazione esplicita sul servizio e sui limiti di data e ora, SHPROHLI può prenotare o confermare un solo appuntamento con il destinatario. Per confermarne uno esistente servono la data e l'ora esatte. Per una nuova prenotazione viene scelto il primo orario proposto che rispetta i tuoi limiti. Sono esclusi spostamenti, cancellazioni, pagamenti, acconti e nuove condizioni finanziarie o di cancellazione. Il destinatario deve confermare l'appuntamento durante la chiamata: una proposta da sola non è una conferma. SHPROHLI non ha accesso alla sua agenda."},{"group":"page:faq","locale":"it","semantic":"accuracy","old":["No. Le trascrizioni in diretta e finali sono generate dall'IA e possono contenere errori. Verifica nomi, date, numeri e impegni importanti sulla registrazione finché è disponibile."],"next":"No. Le trascrizioni IA possono contenere errori. SHPROHLI salva normalmente la trascrizione prodotta durante la conversazione. Se non è disponibile o è incompleta, può essere trascritta la registrazione. Traduzioni, riepiloghi ed esportazioni PDF usano la trascrizione salvata. Verifichi i dettagli importanti nella registrazione disponibile."},{"group":"collection:faq","locale":"it","semantic":"accuracy","old":["No. Le trascrizioni in diretta e finali sono generate dall'IA e possono contenere errori. Verifica nomi, date, numeri e impegni importanti sulla registrazione finché è disponibile."],"next":"No. Le trascrizioni IA possono contenere errori. SHPROHLI salva normalmente la trascrizione prodotta durante la conversazione. Se non è disponibile o è incompleta, può essere trascritta la registrazione. Traduzioni, riepiloghi ed esportazioni PDF usano la trascrizione salvata. Verifichi i dettagli importanti nella registrazione disponibile."},{"group":"collection:landing","locale":"it","semantic":"step","old":["Segui la trascrizione in diretta e consulta quella finale dopo la chiamata."],"next":"Segua la trascrizione della conversazione e la rilegga dopo la chiamata."},{"group":"collection:landing","locale":"it","semantic":"retention","old":["Scegli se eliminare la registrazione dopo la trascrizione finale o conservarla per 7 o 30 giorni."],"next":"Può scegliere se eliminare la registrazione dopo il salvataggio della trascrizione della conversazione o conservarla per 7 o 30 giorni."},{"group":"page:privacy","locale":"rm","semantic":"transcript","old":["Suenter il consentiment po SHPROHLI mussar ina transcripziun en directa e crear la transcripziun finala sin basa da la registraziun. Quests texts vegnan generads da l’IA e pon cuntegnair sbagls. Controllescha nums, datas, cifras ed empermischuns impurtantas cun la registraziun uschè ditg ch’ella è disponibla."],"next":"Suenter il consentiment mussa SHPROHLI la transcripziun durant il discurs e la memorisescha suenter. Sch’ella manca u n’è betg cumpletta, po la registraziun vegnir transcritta empè. La transcripziun memorisada è la basa per translaziuns, resumaziuns ed exports PDF. L’IA po far sbagls. Controllai nums, datas, cifras ed empermischuns impurtantas cun la registraziun uschè ditg ch’ella è disponibla."},{"group":"page:privacy","locale":"rm","semantic":"retention","old":["Per mintga telefonat tschernas ti sche l’audio vegn stizzà suenter la transcripziun finala u conservà durant 7 u 30 dis. L’emprima opziun cumpiglia tuttina ina registraziun temporara e na stizza betg la transcripziun. Translaziuns e resumaziuns na prolungheschan betg la conservaziun da l’audio. Autras datas dal conto e dals telefonats, inclus translaziuns e resumaziuns memorisadas, restan conservadas uschè ditg sco necessari per porscher e proteger il servetsch, respectar tes parameters ed ademplir las obligaziuns applicablas."],"next":"Per mintga telefonat tschernas ti sche l’audio vegn stizzà suenter la memorisaziun da la transcripziun dal discurs u conservà durant 7 u 30 dis. L’emprima opziun cumpiglia tuttina ina registraziun temporara e na stizza betg la transcripziun. Translaziuns e resumaziuns na prolungheschan betg la conservaziun da l’audio. Autras datas dal conto e dals telefonats, inclus translaziuns e resumaziuns memorisadas, restan conservadas uschè ditg sco necessari per porscher e proteger il servetsch, respectar tes parameters ed ademplir las obligaziuns applicablas."},{"group":"page:terms","locale":"rm","semantic":"service","old":["Avant il telefonat controllas ti il plan e las infurmaziuns che l'assistent dastga cundivider. Durant il discurs dovra SHPROHLI questas infurmaziuns tenor basegn. Ti pos suandar la transcripziun e terminar il telefonat. SHPROHLI sa preschenta sco assistent d'IA e dumonda la persuna sche il discurs dastga vegnir registrà e transcrit. L'IA analisescha la resposta per renconuscher la decisiun. Il discurs principal e la registraziun cumenzan pir suenter il consentiment. SHPROHLI po mussar ina transcripziun en directa e crear ina transcripziun finala suenter il telefonat. Cun tia permissiun explicita per la prestaziun e per ils cunfins da data ed ura po SHPROHLI fixar u confermar in sulet termin cun la persuna telefonada. Per confermar in termin existent dovri la data e l'ura exactas. Per in nov termin vegn tschernida l'emprima proposta che correspunda a tes cunfins. Spustaments, annullaziuns, pajaments, acunts e novas cundiziuns finanzialas u d'annullaziun èn exclus. La persuna telefonada sto confermar il termin durant il telefonat; ina proposta suletta n'è betg ina conferma. SHPROHLI n'ha nagin access a ses chalender."],"next":"Avant il telefonat controllas ti il plan e las infurmaziuns che l'assistent dastga cundivider. Durant il discurs dovra SHPROHLI questas infurmaziuns tenor basegn. Ti pos suandar la transcripziun e terminar il telefonat. SHPROHLI sa preschenta sco assistent d'IA e dumonda la persuna sche il discurs dastga vegnir registrà e transcrit. L'IA analisescha la resposta per renconuscher la decisiun. Il discurs principal e la registraziun cumenzan pir suenter il consentiment. SHPROHLI mussa la transcripziun dal discurs e la memorisescha suenter il telefonat; la transcripziun da la registraziun serva sco alternativa. Cun tia permissiun explicita per la prestaziun e per ils cunfins da data ed ura po SHPROHLI fixar u confermar in sulet termin cun la persuna telefonada. Per confermar in termin existent dovri la data e l'ura exactas. Per in nov termin vegn tschernida l'emprima proposta che correspunda a tes cunfins. Spustaments, annullaziuns, pajaments, acunts e novas cundiziuns finanzialas u d'annullaziun èn exclus. La persuna telefonada sto confermar il termin durant il telefonat; ina proposta suletta n'è betg ina conferma. SHPROHLI n'ha nagin access a ses chalender."},{"group":"page:faq","locale":"rm","semantic":"accuracy","old":["Na. Las transcripziuns en directa e finalas vegnan generadas cun IA e pon cuntegnair sbagls. Controlla nums, datas, dumbers ed empermischuns impurtantas cun la registraziun uschè ditg ch'ella è disponibla."],"next":"Na. Transcripziuns d’IA pon cuntegnair sbagls. SHPROHLI memorisescha normalmain la transcripziun creada durant il discurs. Sch’ella manca u n’è betg cumpletta, po la registraziun vegnir transcritta empè. Translaziuns, resumaziuns ed exports PDF dovran la transcripziun memorisada. Controllai detagls impurtants cun la registraziun disponibla."},{"group":"collection:faq","locale":"rm","semantic":"accuracy","old":["Na. Las transcripziuns en directa e finalas vegnan generadas cun IA e pon cuntegnair sbagls. Controlla nums, datas, dumbers ed empermischuns impurtantas cun la registraziun uschè ditg ch'ella è disponibla."],"next":"Na. Transcripziuns d’IA pon cuntegnair sbagls. SHPROHLI memorisescha normalmain la transcripziun creada durant il discurs. Sch’ella manca u n’è betg cumpletta, po la registraziun vegnir transcritta empè. Translaziuns, resumaziuns ed exports PDF dovran la transcripziun memorisada. Controllai detagls impurtants cun la registraziun disponibla."},{"group":"collection:landing","locale":"rm","semantic":"step","old":["Suonda la transcripziun en directa e legia suenter la transcripziun finala."],"next":"Suandai la transcripziun dal discurs e legiai ella anc ina giada suenter il telefonat."},{"group":"collection:landing","locale":"rm","semantic":"retention","old":["Ti tschernas sche la registraziun vegn stizzada suenter la transcripziun finala u conservada per 7 u 30 dis."],"next":"Vus tschernis sche la registraziun vegn stizzada suenter la memorisaziun da la transcripziun dal discurs u conservada durant 7 u 30 dis."},{"group":"page:privacy","locale":"ru","semantic":"transcript","old":["После согласия SHPROHLI может показывать расшифровку в реальном времени и создавать итоговую из записи. Эти тексты создаёт ИИ, в них возможны ошибки. Пока запись доступна, сверяйте с ней важные имена, даты, числа и обязательства."],"next":"После согласия SHPROHLI показывает расшифровку во время разговора и сохраняет её после звонка. Если она недоступна или неполна, вместо неё может использоваться расшифровка аудиозаписи. Сохранённый текст служит источником для перевода, резюме и PDF. ИИ может ошибаться. Сверяйте важные имена, даты, числа и договорённости с записью, пока она доступна."},{"group":"page:privacy","locale":"ru","semantic":"retention","old":["Для каждого звонка вы выбираете: удалить аудио после итоговой расшифровки или хранить 7 либо 30 дней. Первый вариант всё равно предполагает временную запись и не удаляет расшифровку. Перевод и сводки не продлевают срок хранения аудио. Остальные данные аккаунта и звонков, включая сохранённые переводы и сводки, хранятся, пока нужны для работы и защиты сервиса, соблюдения настроек и применимых обязательств."],"next":"Для каждого звонка вы выбираете: удалить аудио после сохранения расшифровки разговора или хранить 7 либо 30 дней. Первый вариант всё равно предполагает временную запись и не удаляет расшифровку. Перевод и сводки не продлевают срок хранения аудио. Остальные данные аккаунта и звонков, включая сохранённые переводы и сводки, хранятся, пока нужны для работы и защиты сервиса, соблюдения настроек и применимых обязательств."},{"group":"page:terms","locale":"ru","semantic":"service","old":["Перед звонком вы проверяете план и сведения, которыми ассистенту разрешено делиться. Во время разговора SHPROHLI использует их по мере необходимости. Вы можете следить за расшифровкой и остановить звонок. SHPROHLI представляется ИИ-ассистентом и спрашивает собеседника, можно ли записывать и расшифровывать разговор. ИИ обрабатывает ответ, чтобы распознать выбор. Основной разговор и запись начинаются только после согласия. SHPROHLI может показывать расшифровку в реальном времени и создавать итоговую после звонка. Если вы явно одобрили услугу и ограничения по дате и времени, SHPROHLI может записать вас на один приём или подтвердить существующую запись у собеседника. Для подтверждения нужны точные дата и время. При новой записи выбирается первое предложенное время, которое соответствует вашим условиям. Переносы, отмены, платежи, предоплата и новые финансовые условия или условия отмены исключены. Собеседник должен подтвердить запись во время звонка: одного предложения времени недостаточно. У SHPROHLI нет доступа к его календарю."],"next":"Перед звонком вы проверяете план и сведения, которыми ассистенту разрешено делиться. Во время разговора SHPROHLI использует их по мере необходимости. Вы можете следить за расшифровкой и остановить звонок. SHPROHLI представляется ИИ-ассистентом и спрашивает собеседника, можно ли записывать и расшифровывать разговор. ИИ обрабатывает ответ, чтобы распознать выбор. Основной разговор и запись начинаются только после согласия. SHPROHLI показывает расшифровку разговора и сохраняет её после звонка; распознавание аудиозаписи используется как резервный вариант. Если вы явно одобрили услугу и ограничения по дате и времени, SHPROHLI может записать вас на один приём или подтвердить существующую запись у собеседника. Для подтверждения нужны точные дата и время. При новой записи выбирается первое предложенное время, которое соответствует вашим условиям. Переносы, отмены, платежи, предоплата и новые финансовые условия или условия отмены исключены. Собеседник должен подтвердить запись во время звонка: одного предложения времени недостаточно. У SHPROHLI нет доступа к его календарю."},{"group":"page:faq","locale":"ru","semantic":"accuracy","old":["Нет. ИИ может ошибаться и в текущей, и в итоговой расшифровке. Сверяйте важные имена, даты, числа и договорённости с записью, пока она доступна."],"next":"Нет. В расшифровке ИИ возможны ошибки. Обычно SHPROHLI сохраняет текст, полученный во время разговора. Если он недоступен или неполон, вместо него может использоваться расшифровка записи. Перевод, резюме и PDF используют сохранённый текст. Сверяйте важные сведения с записью, пока она доступна."},{"group":"collection:faq","locale":"ru","semantic":"accuracy","old":["Нет. ИИ может ошибаться и в текущей, и в итоговой расшифровке. Сверяйте важные имена, даты, числа и договорённости с записью, пока она доступна."],"next":"Нет. В расшифровке ИИ возможны ошибки. Обычно SHPROHLI сохраняет текст, полученный во время разговора. Если он недоступен или неполон, вместо него может использоваться расшифровка записи. Перевод, резюме и PDF используют сохранённый текст. Сверяйте важные сведения с записью, пока она доступна."},{"group":"collection:landing","locale":"ru","semantic":"step","old":["Следите за текстом разговора в реальном времени, а затем прочитайте итоговую расшифровку."],"next":"Следите за расшифровкой разговора и возвращайтесь к ней после звонка."},{"group":"collection:landing","locale":"ru","semantic":"retention","old":["Вы выбираете, удалить запись после итоговой расшифровки или хранить её 7 либо 30 дней."],"next":"Вы выбираете, удалить запись после сохранения расшифровки разговора или хранить её 7 либо 30 дней."},{"group":"page:privacy","locale":"uk","semantic":"transcript","old":["Після згоди SHPROHLI може показувати розшифровку наживо й створювати підсумкову із запису. Ці тексти створює ШІ, у них можливі помилки. Поки запис доступний, звіряйте з ним важливі імена, дати, числа й зобов’язання."],"next":"Після згоди SHPROHLI показує розшифровку під час розмови й зберігає її після дзвінка. Якщо вона недоступна або неповна, замість неї може використовуватися розшифровка аудіозапису. Збережений текст є джерелом для перекладу, підсумку й PDF. ШІ може помилятися. Звіряйте важливі імена, дати, числа й домовленості із записом, поки він доступний."},{"group":"page:privacy","locale":"uk","semantic":"retention","old":["Для кожного дзвінка ви вибираєте: видалити аудіо після підсумкової розшифровки або зберігати 7 чи 30 днів. Перший варіант однаково передбачає тимчасовий запис і не видаляє розшифровку. Переклад і підсумки не подовжують строку зберігання аудіо. Решта даних облікового запису й дзвінків, зокрема збережені переклади та підсумки, зберігаються, доки потрібні для роботи й захисту сервісу, дотримання налаштувань і застосовних зобов’язань."],"next":"Для кожного дзвінка ви вибираєте: видалити аудіо після збереження розшифровки розмови або зберігати 7 чи 30 днів. Перший варіант однаково передбачає тимчасовий запис і не видаляє розшифровку. Переклад і підсумки не подовжують строку зберігання аудіо. Решта даних облікового запису й дзвінків, зокрема збережені переклади та підсумки, зберігаються, доки потрібні для роботи й захисту сервісу, дотримання налаштувань і застосовних зобов’язань."},{"group":"page:terms","locale":"uk","semantic":"service","old":["Перед дзвінком ви перевіряєте план і відомості, якими асистентові дозволено ділитися. Під час розмови SHPROHLI використовує їх за потреби. Ви можете стежити за розшифруванням і зупинити дзвінок. SHPROHLI представляється ШІ-асистентом і запитує співрозмовника, чи можна записувати й розшифровувати розмову. ШІ обробляє відповідь, щоб розпізнати вибір. Основна розмова й запис починаються лише після згоди. SHPROHLI може показувати розшифрування наживо й створювати підсумкове після дзвінка. Якщо ви явно схвалили послугу й обмеження щодо дати та часу, SHPROHLI може записати вас на один прийом або підтвердити наявний запис у співрозмовника. Для підтвердження потрібні точні дата й час. Для нового запису обирається перший запропонований час, що відповідає вашим умовам. Перенесення, скасування, платежі, передоплата та нові фінансові умови чи умови скасування виключені. Співрозмовник має підтвердити запис під час дзвінка: самої пропозиції часу недостатньо. SHPROHLI не має доступу до його календаря."],"next":"Перед дзвінком ви перевіряєте план і відомості, якими асистентові дозволено ділитися. Під час розмови SHPROHLI використовує їх за потреби. Ви можете стежити за розшифруванням і зупинити дзвінок. SHPROHLI представляється ШІ-асистентом і запитує співрозмовника, чи можна записувати й розшифровувати розмову. ШІ обробляє відповідь, щоб розпізнати вибір. Основна розмова й запис починаються лише після згоди. SHPROHLI показує розшифровку розмови й зберігає її після дзвінка; розпізнавання аудіозапису використовується як резервний варіант. Якщо ви явно схвалили послугу й обмеження щодо дати та часу, SHPROHLI може записати вас на один прийом або підтвердити наявний запис у співрозмовника. Для підтвердження потрібні точні дата й час. Для нового запису обирається перший запропонований час, що відповідає вашим умовам. Перенесення, скасування, платежі, передоплата та нові фінансові умови чи умови скасування виключені. Співрозмовник має підтвердити запис під час дзвінка: самої пропозиції часу недостатньо. SHPROHLI не має доступу до його календаря."},{"group":"page:faq","locale":"uk","semantic":"accuracy","old":["Ні. ШІ може помилятися і в поточному, і в підсумковому розшифруванні. Звіряйте важливі імена, дати, числа й домовленості із записом, поки він доступний."],"next":"Ні. У розшифровці ШІ можливі помилки. Зазвичай SHPROHLI зберігає текст, отриманий під час розмови. Якщо він недоступний або неповний, замість нього може використовуватися розшифровка запису. Переклад, підсумок і PDF використовують збережений текст. Звіряйте важливі відомості із записом, поки він доступний."},{"group":"collection:faq","locale":"uk","semantic":"accuracy","old":["Ні. ШІ може помилятися і в поточному, і в підсумковому розшифруванні. Звіряйте важливі імена, дати, числа й домовленості із записом, поки він доступний."],"next":"Ні. У розшифровці ШІ можливі помилки. Зазвичай SHPROHLI зберігає текст, отриманий під час розмови. Якщо він недоступний або неповний, замість нього може використовуватися розшифровка запису. Переклад, підсумок і PDF використовують збережений текст. Звіряйте важливі відомості із записом, поки він доступний."},{"group":"collection:landing","locale":"uk","semantic":"step","old":["Стежте за текстом розмови наживо, а потім прочитайте підсумкове розшифрування."],"next":"Стежте за розшифровкою розмови й повертайтеся до неї після дзвінка."},{"group":"collection:landing","locale":"uk","semantic":"retention","old":["Ви обираєте, видалити запис після підсумкового розшифрування чи зберігати його 7 або 30 днів."],"next":"Ви обираєте, видалити запис після збереження розшифровки розмови чи зберігати його 7 або 30 днів."}]$copy$::jsonb) a(item)
    WHERE item->>'group'=group_key AND (locale_key IS NULL OR item->>'locale'=locale_key)
  LOOP
    found := pg_temp.transcript_copy_contains(value,rule->>'next') OR EXISTS(
      SELECT 1 FROM jsonb_array_elements_text(rule->'old') a(old) WHERE pg_temp.transcript_copy_contains(value,old));
    IF strict AND NOT found THEN
      RAISE EXCEPTION 'TRANSCRIPT_COPY_PREFLIGHT: % locale % field % has an unknown edit; review it before rollout',group_key,rule->>'locale',rule->>'semantic';
    END IF;
    value := pg_temp.transcript_copy_leaf(value,rule->'old',rule->>'next');
  END LOOP;
  RETURN value;
END; $function$;

DO $$
DECLARE page record; revision record; localized record; collection record;
  next_id uuid; next_number integer; next_sections jsonb; next_snapshot jsonb; changed boolean;
BEGIN
  LOCK TABLE content_page_revisions, content_page_revision_localizations, content_editorial_revisions IN SHARE ROW EXCLUSIVE MODE;
  FOR page IN SELECT * FROM content_pages WHERE key IN ('privacy','terms','faq') LOOP
    SELECT * INTO revision FROM content_page_revisions WHERE page_id=page.id AND status='published' ORDER BY revision_number DESC LIMIT 1;
    IF NOT FOUND THEN CONTINUE; END IF;
    IF (SELECT count(*) FROM content_page_revision_localizations WHERE revision_id=revision.id AND locale IN ('en','de','fr','it','rm','ru','uk')) <> 7 THEN
      RAISE EXCEPTION 'TRANSCRIPT_COPY_PREFLIGHT: page % requires all seven locales',page.key;
    END IF;
    changed := false;
    FOR localized IN SELECT * FROM content_page_revision_localizations WHERE revision_id=revision.id LOOP
      next_sections := pg_temp.transcript_copy_upgrade(localized.sections,'page:'||page.key,localized.locale,true);
      changed := changed OR next_sections<>localized.sections;
    END LOOP;
    IF changed THEN
      next_id := gen_random_uuid();
      SELECT max(revision_number)+1 INTO next_number FROM content_page_revisions WHERE page_id=page.id;
      INSERT INTO content_page_revisions(id,page_id,revision_number,status,requires_reacceptance,created_by_user_id,created_at,updated_at,published_at,required_locales)
        VALUES(next_id,page.id,next_number,'published',false,NULL,now(),now(),now(),'["en","de","fr","it","rm","ru","uk"]');
      INSERT INTO content_page_revision_localizations(id,revision_id,locale,title,summary,sections,seo_title,seo_description,source_revision_number,created_at,updated_at)
        SELECT gen_random_uuid(),next_id,locale,title,summary,pg_temp.transcript_copy_upgrade(sections,'page:'||page.key,locale,true),seo_title,seo_description,next_number,now(),now()
          FROM content_page_revision_localizations WHERE revision_id=revision.id;
      UPDATE content_pages SET updated_at=now() WHERE id=page.id;
    END IF;
    -- Keep existing drafts and their metadata; update only recognized old leaves.
    UPDATE content_page_revision_localizations l SET sections=pg_temp.transcript_copy_upgrade(l.sections,'page:'||page.key,l.locale,false),updated_at=now()
      FROM content_page_revisions r WHERE r.id=l.revision_id AND r.page_id=page.id AND r.status='draft'
        AND l.sections<>pg_temp.transcript_copy_upgrade(l.sections,'page:'||page.key,l.locale,false);
  END LOOP;
  FOR collection IN SELECT * FROM content_editorial_collections WHERE key IN ('faq','landing') LOOP
    SELECT * INTO revision FROM content_editorial_revisions WHERE collection_id=collection.id AND status='published' ORDER BY revision_number DESC LIMIT 1;
    IF NOT FOUND THEN CONTINUE; END IF;
    next_snapshot := pg_temp.transcript_copy_upgrade(revision.snapshot,'collection:'||collection.key,NULL,true);
    IF next_snapshot<>revision.snapshot THEN
      SELECT max(revision_number)+1 INTO next_number FROM content_editorial_revisions WHERE collection_id=collection.id;
      INSERT INTO content_editorial_revisions(id,collection_id,revision_number,status,snapshot,created_by_user_id,created_at,updated_at,published_at,required_locales)
        VALUES(gen_random_uuid(),collection.id,next_number,'published',next_snapshot,NULL,now(),now(),now(),'["en","de","fr","it","rm","ru","uk"]');
      UPDATE content_editorial_collections SET updated_at=now() WHERE id=collection.id;
    END IF;
    UPDATE content_editorial_revisions SET snapshot=pg_temp.transcript_copy_upgrade(snapshot,'collection:'||collection.key,NULL,false),updated_at=now()
      WHERE collection_id=collection.id AND status='draft' AND snapshot<>pg_temp.transcript_copy_upgrade(snapshot,'collection:'||collection.key,NULL,false);
  END LOOP;
END; $$;
DROP FUNCTION pg_temp.transcript_copy_upgrade(jsonb,text,text,boolean);
DROP FUNCTION pg_temp.transcript_copy_contains(jsonb,text);
DROP FUNCTION pg_temp.transcript_copy_leaf(jsonb,jsonb,text);
